import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        StringTokenizer st = new StringTokenizer(br.readLine());
        long x = Long.parseLong(st.nextToken());
        long y = Long.parseLong(st.nextToken());
        long n = Long.parseLong(st.nextToken());

        long gcdxy = gcd(x, y);
        x /= gcdxy;
        y /= gcdxy;
        Pair xy = new Pair(x, y);
        Pair rp = new Pair(1000000000000L, 1);
        Pair rv = new Pair(0, 0);

        for (long b = 1; b <= n; b++) {
            long l = 0, r = 1000000;
            double maxv = (double) x / y;
            maxv += (double) rp.first / rp.second;
            maxv = (maxv + 2) * b;
            r = (long) maxv;

            while (l <= r) {
                long mid = l + (r - l) / 2;
                Pair ab = new Pair(mid, b);
                Pair dif = myAbs(mysub(xy, ab));
                int comp = compare(dif, rp);
                if (comp == 0) {
                    if (ab.second < rv.second)
                        rv = ab;
                    else if (ab.second == rv.second && ab.first < rv.first)
                        rv = ab;
                } else if (comp < 0) {
                    rp = dif;
                    rv = ab;
                }

                if (compare(ab, xy) < 0)
                    l = mid + 1;
                else
                    r = mid - 1;
            }
        }
        out.println(rv.first + "/" + rv.second);
        out.flush();
    }

    static long gcd(long a, long b) {
        while (b != 0) {
            long temp = a % b;
            a = b;
            b = temp;
        }
        return a;
    }

    static long lcm(long a, long b) {
        return a / gcd(a, b) * b;
    }

    static class Pair {
        long first, second;

        Pair(long f, long s) {
            this.first = f;
            this.second = s;
        }
    }

    static Pair mysub(Pair a, Pair b) {
        long cz = lcm(a.second, b.second);
        long ac = cz / a.second;
        long bc = cz / b.second;
        long rt = a.first * ac - b.first * bc;
        long gcdr = gcd(Math.abs(rt), cz);
        return new Pair(rt / gcdr, cz / gcdr);
    }

    static Pair myAbs(Pair a) {
        if (a.first < 0)
            return new Pair(-a.first, a.second);
        return a;
    }

    static int compare(Pair a, Pair b) {
        long cz = lcm(a.second, b.second);
        long ac = cz / a.second;
        long bc = cz / b.second;
        long na = a.first * ac;
        long nb = b.first * bc;
        if (na == nb)
            return 0;
        if (na < nb)
            return -1;
        return 1;
    }
}
